// ─── File: ResilientConsumerDemo.java ───
// Runnable demo: idempotent redelivery + dead-letter for poison messages.
package com.bank.resilientconsumer;

import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.*;

public class ResilientConsumerDemo {

    private static final Logger log = Logger.getLogger("ResilientConsumer");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        InboxStore inbox = new InboxStore();
        BalanceStore balances = new BalanceStore();
        balances.set("CUR3001", new BigDecimal("250000"));
        DeadLetterQueue dlq = new DeadLetterQueue();
        TransferConsumer consumer = new TransferConsumer(inbox, balances, dlq);

        // A valid credit event delivered the FIRST time → applied.
        TransferEvent e1 = new TransferEvent("MSG-001", "SAV2001", "CUR3001",
                new BigDecimal("50000"));
        consumer.onMessage(e1);

        // SAME event redelivered after a simulated crash → MUST be skipped.
        log.warning("Simulating consumer crash + broker redelivery of MSG-001");
        consumer.onMessage(e1);

        log.info(() -> "FINAL CUR3001 balance = Rs." + balances.get("CUR3001"));

        // A poison event (null target) fails every retry → goes to DLQ.
        TransferEvent poison = new TransferEvent("MSG-999", "SAV2001", null,
                new BigDecimal("1000"));
        consumer.onMessage(poison);
        log.info(() -> "DLQ size = " + dlq.size());
    }
}

// ─── event/TransferEvent.java ───
record TransferEvent(String messageId, String fromId, String toId, BigDecimal amount) { }

// ─── inbox/InboxStore.java (idempotency via processed message ids) ───
class InboxStore {
    private final Map<String, Boolean> processed = new ConcurrentHashMap<>();
    // Atomic claim: returns true only for the FIRST caller for this id.
    boolean claim(String messageId) {
        return processed.putIfAbsent(messageId, Boolean.TRUE) == null;
    }
}

// ─── consumer/TransferConsumer.java ───
class TransferConsumer {
    private static final Logger log = Logger.getLogger("ResilientConsumer");
    private static final int MAX_RETRIES = 3;
    private final InboxStore inbox;
    private final BalanceStore balances;
    private final DeadLetterQueue dlq;

    TransferConsumer(InboxStore inbox, BalanceStore balances, DeadLetterQueue dlq) {
        this.inbox = inbox; this.balances = balances; this.dlq = dlq;
    }

    // Simulates a Kafka listener with manual ack AFTER commit + retry + DLQ.
    void onMessage(TransferEvent e) {
        int attempt = 0;
        while (true) {
            attempt++;
            try {
                process(e);
                // ACK only reached after successful processing (and commit).
                log.info(() -> "ACK " + e.messageId() + " after successful processing");
                return;
            } catch (TransientException te) {
                log.warning("Transient failure on " + e.messageId()
                        + " attempt " + attempt + ": " + te.getMessage());
                if (attempt >= MAX_RETRIES) { toDlq(e, te.getMessage()); return; }
            } catch (PoisonException pe) {
                toDlq(e, pe.getMessage()); return;   // never retry poison
            }
        }
    }

    // Idempotent processing: claim the id first; skip if already processed.
    private void process(TransferEvent e) {
        if (e.toId() == null) throw new PoisonException("null target account");
        if (!inbox.claim(e.messageId())) {
            log.info(() -> "DUPLICATE " + e.messageId() + " already processed — skip");
            return;   // idempotent no-op on redelivery
        }
        balances.credit(e.toId(), e.amount());
        log.info(() -> "Credited " + e.toId() + " Rs." + e.amount()
                + " from " + e.messageId());
    }

    private void toDlq(TransferEvent e, String reason) {
        dlq.publish(e, reason);
        log.severe("Routed " + e.messageId() + " to DLQ: " + reason);
    }
}

// ─── dlq/DeadLetterQueue.java ───
class DeadLetterQueue {
    private final Map<String, String> parked = new ConcurrentHashMap<>();
    void publish(TransferEvent e, String reason) { parked.put(e.messageId(), reason); }
    int size() { return parked.size(); }
}

class BalanceStore {
    private final Map<String, BigDecimal> db = new ConcurrentHashMap<>();
    void set(String id, BigDecimal b) { db.put(id, b); }
    void credit(String id, BigDecimal amt) { db.merge(id, amt, BigDecimal::add); }
    BigDecimal get(String id) { return db.get(id); }
}

class TransientException extends RuntimeException { TransientException(String m){super(m);} }
class PoisonException extends RuntimeException { PoisonException(String m){super(m);} }

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
